  "{n} wrong pairs.": "{n} falsche Paare.",
  "{n} year": "{n} Jahr",
  "{n} years": "{n} Jahre",
  "{n}%: listen again and try once more": "{n} %: Hör noch einmal zu und versuch es erneut",
  "{n}%: not quite, try again": "{n} %: nicht ganz, versuch es noch einmal",
  "{n}%: try once more": "{n} %: Versuch es noch einmal",
